<?php require_once 'includes/auth.php';require_customer();if(session_status()!==PHP_SESSION_ACTIVE)session_start();if(empty($_SESSION['cart'])){header('Location: cart.php');exit;}$c=current_customer();$e=[];$ids=array_keys($_SESSION['cart']);$in=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM products WHERE id IN($in) AND active=1");$s->execute($ids);$items=[];$total=0;foreach($s as $p){$p['quantity']=$_SESSION['cart'][$p['id']];if($p['quantity']>$p['stock'])$e[]=$p['name'].' has insufficient stock.';$p['subtotal']=$p['quantity']*$p['price'];$total+=$p['subtotal'];$items[]=$p;}if($_SERVER['REQUEST_METHOD']==='POST'&&!$e){$ph=preg_replace('/\D+/','',$_POST['mpesa_phone']??'');$ad=trim($_POST['delivery_address']??'');if(substr($ph,0,1)==='0')$ph='254'.substr($ph,1);if(!preg_match('/^2547\d{8}$/',$ph))$e[]='Use M-PESA number 2547XXXXXXXX.';if(!$ad)$e[]='Delivery address is required.';if(!$e){$pdo=db();$pdo->beginTransaction();try{$s=$pdo->prepare("INSERT INTO orders(customer_id,customer_name,phone,email,delivery_address,total,payment_status,order_status)VALUES(?,?,?,?,?,?, 'Pending','Pending')");$s->execute([$c['id'],$c['name'],$ph,$c['email'],$ad,$total]);$oid=$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price,subtotal)VALUES(?,?,?,?,?,?)');foreach($items as $p)$s->execute([$oid,$p['id'],$p['name'],$p['quantity'],$p['price'],$p['subtotal']]);$pdo->commit();require_once 'mpesa.php';$r=mpesa_stk_push($ph,$total,$oid);if(!$r['success']){db()->prepare("UPDATE orders SET payment_status='Failed' WHERE id=?")->execute([$oid]);$e[]=$r['message'];}else{db()->prepare('UPDATE orders SET merchant_request_id=?,checkout_request_id=? WHERE id=?')->execute([$r['MerchantRequestID'],$r['CheckoutRequestID'],$oid]);header('Location: payment_status.php?order='.$oid);exit;}}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$e[]='Order creation failed: '.$x->getMessage();}}}$title='Checkout - '.APP_NAME;include 'includes/header.php';?><h1>Checkout</h1><div class="notice">Logged in as <?=htmlspecialchars($c['email'])?></div><?php foreach($e as $x):?><div class="notice error"><?=htmlspecialchars($x)?></div><?php endforeach;?><form class="form" method="post"><label>M-PESA Phone<input name="mpesa_phone" value="<?=htmlspecialchars($c['phone'])?>" required></label><label>Delivery Address<textarea name="delivery_address" required><?=htmlspecialchars($c['address'])?></textarea></label><h3>Total: KES <?=number_format($total,2)?></h3><button class="btn">Place Order & Request M-PESA Payment</button></form><?php include 'includes/footer.php';?>